WITH event_def AS (SELECT '佩恩' period,DATE '2026-07-15' start_date,DATE '2026-07-21' end_date UNION ALL SELECT '西索',DATE '2026-07-29',DATE '2026-08-04'), blacklist AS (SELECT DISTINCT "#varchar_id" account_id FROM user_result_cluster_23 WHERE cluster_name IN ('internal_users','is_water','is_water_mod','suspicious_ip')), wallet AS (SELECT CAST(lcxtransactionid AS VARCHAR) purchaseid,MAX(ABS(CAST(freeamount AS DOUBLE))) freeamount FROM ta.v_event_16 WHERE "$part_event"='LCX_WALLET_SPEND_TRANSACTION' AND "$part_date" BETWEEN '2026-07-15' AND '2026-08-04' GROUP BY 1), product_dim AS (SELECT join_key,MAX(product_category) product_category,MAX(product_name) product_name FROM (SELECT CASE WHEN lower("payload.productid@product_id") LIKE '%google.open%' THEN element_at(split(element_at(split("payload.productid@product_id",'.'),-1),'_'),1) ELSE "payload.productid@product_id" END join_key,"payload.productid@product_category" product_category,"payload.productid@product_name" product_name FROM ta_dim.dim_23_0_51243 WHERE "payload.productid@product_id" IS NOT NULL) x GROUP BY 1), purchases AS (SELECT e.period,COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id") account_id,CAST(v."#event_time" AS timestamp(3)) purchase_time,regexp_replace(element_at(split(v.payload.productid,'.'),-1),'KOL$','') productid,CASE WHEN v.payload.productid LIKE 'dirc.%' THEN regexp_replace(element_at(split(v.payload.productid,'.'),-1),'KOL$','') ELSE v.payload.productid END join_key,CAST(v.payload.storeorderid AS VARCHAR) storeorderid,(CAST(v.payload.curamt AS DOUBLE)-COALESCE(w.freeamount,0))/COALESCE(x.exchange,1)*(COALESCE(TRY_CAST(SPLIT(v.payload.purchaseeventpayload,'|')[3] AS INTEGER),100)/100.000) revenue_usd FROM event_def e JOIN ta.v_event_23 v ON v."$part_event"='PURCHASE' AND v."$part_date" BETWEEN CAST(e.start_date AS VARCHAR) AND CAST(e.end_date AS VARCHAR) LEFT JOIN blacklist b ON COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id")=b.account_id LEFT JOIN wallet w ON CAST(v.payload.purchaseid AS VARCHAR)=w.purchaseid LEFT JOIN ta_dim.ta_exchange x ON v."$part_date"=x.ex_date AND v.payload.cur=x.currency WHERE COALESCE(v.payload.validationtype,'')<>'SANDBOX_RECEIPT' AND b.account_id IS NULL), small_users AS (SELECT period,account_id,SUM(revenue_usd) user_revenue FROM purchases GROUP BY 1,2 HAVING SUM(revenue_usd)>0 AND SUM(revenue_usd)<=10), small_purchase AS (SELECT p.*,COALESCE(d.product_category,'未映射') product_category,COALESCE(d.product_name,p.productid) product_name,ROW_NUMBER() OVER(PARTITION BY p.period,p.account_id ORDER BY p.purchase_time,p.storeorderid,p.productid) first_rn FROM purchases p JOIN small_users u ON p.period=u.period AND p.account_id=u.account_id LEFT JOIN product_dim d ON p.join_key=d.join_key), cohort_size AS (SELECT period,COUNT(*) cohort_users FROM small_users GROUP BY 1), result AS (SELECT '首个付费商品' attribution_type,period,product_category,productid,product_name,COUNT(DISTINCT account_id) users,COUNT(*) orders,SUM(revenue_usd) revenue_usd FROM small_purchase WHERE first_rn=1 GROUP BY 1,2,3,4,5 UNION ALL SELECT '购买过的商品',period,product_category,productid,product_name,COUNT(DISTINCT account_id),COUNT(*),SUM(revenue_usd) FROM small_purchase GROUP BY 1,2,3,4,5) SELECT r.attribution_type,r.period,r.product_category,r.productid,r.product_name,r.users,c.cohort_users,ROUND(CAST(r.users AS DOUBLE)/c.cohort_users,4) user_share,r.orders,ROUND(r.revenue_usd,2) revenue_usd,ROUND(r.revenue_usd/r.users,2) revenue_per_user FROM result r JOIN cohort_size c ON r.period=c.period ORDER BY r.attribution_type,r.period,r.users DESC;
